CREATE TABLE sqlite_sequence(name,seq);
CREATE TABLE `adonis_schema` (`id` integer not null primary key autoincrement, `name` varchar(255) not null, `batch` integer not null, `migration_time` datetime default CURRENT_TIMESTAMP);
CREATE TABLE `adonis_schema_versions` (`version` integer, primary key (`version`));
CREATE TABLE `users` (`id` integer not null primary key autoincrement, `full_name` varchar(255) null, `email` varchar(254) not null, `password` varchar(255) not null, `created_at` datetime not null, `updated_at` datetime null, `role` varchar(32) not null default 'member', `session_version` integer not null default '1');
CREATE UNIQUE INDEX `users_email_unique` on `users` (`email`);
CREATE TABLE `invites` (`id` integer not null primary key autoincrement, `token` varchar(64) not null, `email` varchar(254) not null, `role` varchar(32) not null default 'member', `created_by` integer not null, `accepted_at` datetime null, `expires_at` datetime not null, `created_at` datetime not null, `updated_at` datetime null, foreign key(`created_by`) references `users`(`id`) on delete CASCADE);
CREATE UNIQUE INDEX `invites_token_unique` on `invites` (`token`);
CREATE TABLE `access_token_mcps` (`id` integer not null primary key autoincrement, `access_token_id` integer not null, `mcp_id` integer not null, `created_at` datetime not null, `updated_at` datetime null, foreign key(`access_token_id`) references `access_tokens`(`id`) on delete CASCADE, foreign key(`mcp_id`) references `mcps`(`id`) on delete CASCADE);
CREATE UNIQUE INDEX `access_token_mcps_access_token_id_mcp_id_unique` on `access_token_mcps` (`access_token_id`, `mcp_id`);
CREATE TABLE `remember_me_tokens` (`id` integer not null primary key autoincrement, `tokenable_id` integer not null, `hash` varchar(255) not null, `created_at` datetime not null, `updated_at` datetime not null, `expires_at` datetime not null, foreign key(`tokenable_id`) references `users`(`id`) on delete CASCADE);
CREATE UNIQUE INDEX `remember_me_tokens_hash_unique` on `remember_me_tokens` (`hash`);
CREATE TABLE `instance_settings` (`id` integer not null primary key autoincrement, `mcp_log_level` varchar(16) not null default 'metadata', `mcp_log_retention_days` integer not null default '14', `updated_by` integer null, `created_at` datetime not null, `updated_at` datetime null, `gateway_tool_mode` varchar(16) not null default 'eager', `mcp_auto_update_enabled` boolean not null default '0', `mcp_auto_update_cron` varchar(64) not null default '0 2 * * *', foreign key(`updated_by`) references `users`(`id`) on delete SET NULL);
CREATE TABLE `mcp_call_logs` (`id` integer not null primary key autoincrement, `access_token_id` integer null, `access_token_name` varchar(120) not null, `access_token_prefix` varchar(16) not null, `mcp_id` integer null, `mcp_name` varchar(120) null, `mcp_slug` varchar(120) null, `requested_tool_name` varchar(512) not null, `tool_name` varchar(254) null, `outcome` varchar(16) not null, `error_category` varchar(32) null, `error_summary` varchar(500) null, `arguments` text null, `arguments_captured` boolean not null default '0', `duration_ms` integer not null, `created_at` datetime not null, `response` text null, `response_captured` boolean not null default '0', `caller_ip` varchar(64) null, foreign key(`access_token_id`) references `access_tokens`(`id`) on delete SET NULL, foreign key(`mcp_id`) references `mcps`(`id`) on delete SET NULL);
CREATE INDEX `mcp_call_logs_created_at_index` on `mcp_call_logs` (`created_at`);
CREATE INDEX `mcp_call_logs_outcome_created_at_index` on `mcp_call_logs` (`outcome`, `created_at`);
CREATE INDEX `mcp_call_logs_mcp_slug_created_at_index` on `mcp_call_logs` (`mcp_slug`, `created_at`);
CREATE INDEX `mcp_call_logs_access_token_prefix_created_at_index` on `mcp_call_logs` (`access_token_prefix`, `created_at`);
CREATE TABLE "mcps" (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL, `name` varchar(120) NOT NULL, `slug` varchar(120) NOT NULL, `description` varchar(500) NULL, `transport` varchar(16) NOT NULL, `http_url` varchar(2048) NULL, `npm_package` varchar(254) NULL, `npm_version` varchar(64) NULL, `npm_args` text NULL, `auth_type` varchar(16) NOT NULL DEFAULT 'auto', `auth_bearer` text NULL, `auth_header_name` varchar(120) NULL, `auth_header_value` text NULL, `oauth_authorize_url` varchar(2048) NULL, `oauth_token_url` varchar(2048) NULL, `oauth_scopes` varchar(500) NULL, `oauth_client_id` varchar(254) NULL, `oauth_client_secret` text NULL, `oauth_access_token` text NULL, `oauth_refresh_token` text NULL, `oauth_token_expires_at` datetime NULL, `status` varchar(16) NOT NULL DEFAULT 'draft', `last_error` text NULL, `enabled` boolean NOT NULL DEFAULT '1', `created_by` integer NOT NULL, `created_at` datetime NOT NULL, `updated_at` datetime NULL, `oauth_issuer` varchar(2048) NULL, `oauth_resource` varchar(2048) NULL, `oauth_redirect_uri` varchar(2048) NULL, `oauth_client_auth_method` varchar(64) NULL, `oauth_token_type` varchar(64) NULL, `npm_env` text NULL, `oauth_required` boolean NOT NULL DEFAULT '0', `builtin_key` varchar(64) null, `builtin_write_enabled` boolean not null default '0', `builtin_username` varchar(254) null, `builtin_password` text null, `builtin_permissions` text null, `builtin_aliases` text null, `tool_approvals` text null, `builtin_settings` text null, FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE CASCADE);
CREATE UNIQUE INDEX `mcps_slug_unique` on `mcps` (`slug`);
CREATE TABLE `rate_limits` (`key` varchar(255) not null, `points` integer not null default '0', `expire` bigint, primary key (`key`));
CREATE TABLE `oauth_clients` (`id` integer not null primary key autoincrement, `client_id` varchar(80) not null, `client_secret_hash` varchar(64) null, `client_secret_prefix` varchar(20) null, `client_secret_expires_at` datetime null, `client_name` varchar(120) not null, `redirect_uris` text not null, `token_endpoint_auth_method` varchar(32) not null, `grant_types` text not null, `response_types` text not null, `scope` varchar(500) not null, `created_at` datetime not null, `updated_at` datetime null);
CREATE UNIQUE INDEX `oauth_clients_client_id_unique` on `oauth_clients` (`client_id`);
CREATE TABLE `oauth_authorization_codes` (`id` integer not null primary key autoincrement, `code_hash` varchar(64) not null, `oauth_client_id` integer not null, `user_id` integer not null, `redirect_uri` varchar(2048) not null, `code_challenge` varchar(128) not null, `scopes` varchar(500) not null, `resource` varchar(2048) not null, `expires_at` datetime not null, `created_at` datetime not null, foreign key(`oauth_client_id`) references `oauth_clients`(`id`) on delete CASCADE, foreign key(`user_id`) references `users`(`id`) on delete CASCADE);
CREATE UNIQUE INDEX `oauth_authorization_codes_code_hash_unique` on `oauth_authorization_codes` (`code_hash`);
CREATE TABLE "access_tokens" (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL, `name` varchar(120) NOT NULL, `token_prefix` varchar(16) NOT NULL, `token_hash` varchar(64) NOT NULL, `scope_mode` varchar(16) NOT NULL DEFAULT 'all', `expires_at` datetime NULL, `revoked_at` datetime NULL, `last_used_at` datetime NULL, `created_by` integer NOT NULL, `created_at` datetime NOT NULL, `updated_at` datetime NULL, `source` varchar(16) NOT NULL DEFAULT 'manual', `oauth_client_id` integer NULL, `oauth_scopes` varchar(500) NULL, `oauth_resource` varchar(2048) NULL, `oauth_refresh_token_hash` varchar(64) NULL, `oauth_refresh_token_prefix` varchar(20) NULL, `oauth_refresh_expires_at` datetime NULL, FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE CASCADE, FOREIGN KEY (`oauth_client_id`) REFERENCES `oauth_clients` (`id`) ON DELETE SET NULL);
CREATE UNIQUE INDEX `access_tokens_token_hash_unique` on `access_tokens` (`token_hash`);
CREATE UNIQUE INDEX `access_tokens_oauth_refresh_token_hash_unique` on `access_tokens` (`oauth_refresh_token_hash`);
CREATE TABLE `oauth_refresh_token_history` (`id` integer not null primary key autoincrement, `access_token_id` integer not null, `token_hash` varchar(64) not null, `invalidated_at` datetime not null, foreign key(`access_token_id`) references `access_tokens`(`id`) on delete CASCADE);
CREATE UNIQUE INDEX `oauth_refresh_token_history_token_hash_unique` on `oauth_refresh_token_history` (`token_hash`);
CREATE INDEX `oauth_refresh_token_history_access_token_id_index` on `oauth_refresh_token_history` (`access_token_id`);
CREATE TABLE `approval_requests` (`id` integer not null primary key autoincrement, `public_id` varchar(64) not null, `mcp_id` integer not null, `access_token_id` integer not null, `tool_name` varchar(254) not null, `arguments` text not null, `arguments_hash` varchar(64) not null, `summary` text not null, `status` varchar(16) not null default 'pending', `decided_by` integer null, `decided_at` datetime null, `consumed_at` datetime null, `expires_at` datetime not null, `created_at` datetime not null, `updated_at` datetime null, foreign key(`mcp_id`) references `mcps`(`id`) on delete CASCADE, foreign key(`access_token_id`) references `access_tokens`(`id`) on delete CASCADE, foreign key(`decided_by`) references `users`(`id`) on delete SET NULL);
CREATE UNIQUE INDEX `approval_requests_public_id_unique` on `approval_requests` (`public_id`);
CREATE INDEX `approval_requests_access_token_id_mcp_id_tool_name_arguments_hash_index` on `approval_requests` (`access_token_id`, `mcp_id`, `tool_name`, `arguments_hash`);
CREATE INDEX `approval_requests_status_expires_at_index` on `approval_requests` (`status`, `expires_at`);
